// src/components/Timeline/duplicate-selected-timeline-item.ts
var confirmDuplicatingProgrammaticallyDuplicatedSequences = (nodePathInfos, confirm) => {
  if (nodePathInfos.length === 0) {
    return Promise.resolve(true);
  }
  if (nodePathInfos.length === 1) {
    const [nodePathInfo] = nodePathInfos;
    return confirm({
      title: "Duplicate sequence?",
      message: "This sequence is programmatically duplicated " + nodePathInfo.numberOfSequencesWithThisNodePath + " times in the code. Duplicating inserts another copy. Continue?",
      confirmLabel: "Duplicate"
    });
  }
  return confirm({
    title: "Duplicate sequences?",
    message: nodePathInfos.length + " selected sequences are programmatically duplicated in the code. Duplicating inserts another copy of each. Continue?",
    confirmLabel: "Duplicate"
  });
};
var duplicateSequence = (nodePathInfo) => {
  const nodePath = nodePathInfo.sequenceSubscriptionKey;
  return callApi("/api/duplicate-jsx-node", {
    fileName: nodePath.absolutePath,
    nodePath: nodePath.nodePath
  });
};
var duplicateSequencesFromSource = (nodePathInfos, confirm) => {
  const programmaticallyDuplicated = nodePathInfos.filter((nodePathInfo) => nodePathInfo.numberOfSequencesWithThisNodePath > 1);
  const regular = nodePathInfos.filter((nodePathInfo) => nodePathInfo.numberOfSequencesWithThisNodePath <= 1);
  return confirmDuplicatingProgrammaticallyDuplicatedSequences(programmaticallyDuplicated, confirm).then((shouldDuplicateProgrammaticSequences) => {
    const toDuplicate = [...regular];
    if (shouldDuplicateProgrammaticSequences) {
      toDuplicate.push(...programmaticallyDuplicated);
    }
    if (toDuplicate.length === 0) {
      return Promise.resolve();
    }
    return Promise.all(toDuplicate.map(duplicateSequence)).then((results) => {
      const failedResult = results.find((result) => !result.success);
      if (failedResult && !failedResult.success) {
        showNotification(failedResult.reason, 4000);
        return;
      }
      showNotification(toDuplicate.length === 1 ? "Duplicated sequence in source file" : "Duplicated sequences in source files", 2000);
    }).catch((err) => {
      showNotification(err.message, 4000);
    });
  });
};
var isDuplicatableSequenceRowSelection = (selection) => selection.type === "sequence";
var isDuplicatableEffectSelection = (selection) => selection.type === "sequence-effect";
var duplicateEffectsFromSource = (effects) => {
  return callApi("/api/duplicate-effect", effects.map((effect) => {
    const nodePath = effect.nodePathInfo.sequenceSubscriptionKey;
    return {
      fileName: nodePath.absolutePath,
      sequenceNodePath: nodePath,
      effectIndex: effect.i
    };
  })).then((result) => {
    if (result.success) {
      showNotification(effects.length === 1 ? "Duplicated effect in source file" : "Duplicated effects in source files", 2000);
    } else {
      showNotification(result.reason, 4000);
    }
  }).catch((err) => {
    showNotification(err.message, 4000);
  });
};
var duplicateSelectedTimelineItems = ({
  selections,
  confirm
}) => {
  const sequenceSelections = selections.filter(isDuplicatableSequenceRowSelection);
  if (sequenceSelections.length > 0) {
    return duplicateSequencesFromSource(sequenceSelections.map((selection) => selection.nodePathInfo), confirm);
  }
  const effectSelections = selections.filter(isDuplicatableEffectSelection);
  if (effectSelections.length === 0) {
    return null;
  }
  return duplicateEffectsFromSource(effectSelections);
};

